export function targetId(href){if(!href.startsWith("#")||href.length<2)return undefined;const raw=href.slice(1);try{return decodeURIComponent(raw);}catch{return raw;}}
export function definitionText(doc,href){const id=targetId(href);if(id===undefined)return undefined;const target=doc.getElementById(id);if(target===null)return undefined;const copy=target.cloneNode(true);for(const backref of Array.from(copy.querySelectorAll("[data-footnote-backref]")))backref.remove();const text=(copy.textContent??"").replace(/\s+/g," ").trim();return text===""?undefined:text;}
export function activate(refs,popover,doc){if(refs.length===0)return false;let shown;let previousDescription=null;const hide=()=>{if(shown===undefined)return;if(previousDescription===null)shown.removeAttribute("aria-describedby");else shown.setAttribute("aria-describedby",previousDescription);shown=undefined;previousDescription=null;popover.hidden=true;popover.textContent="";};const show=(ref)=>{const href=ref.getAttribute("href");if(href===null)return;const text=definitionText(doc,href);if(text===undefined)return;const anchor=ref.parentNode;if(anchor===null)return;if(shown!==ref){hide();previousDescription=ref.getAttribute("aria-describedby");if(popover.id!=="")ref.setAttribute("aria-describedby",popover.id);}
popover.textContent=text;anchor.setAttribute("data-footnote-anchor","true");anchor.appendChild(popover);popover.hidden=false;shown=ref;};for(const ref of refs){ref.addEventListener("mouseenter",()=>show(ref));ref.addEventListener("mouseleave",hide);ref.addEventListener("focus",()=>show(ref));ref.addEventListener("blur",hide);}
doc.addEventListener("keydown",(event)=>{if(event.key==="Escape")hide();});return true;}
const globals=globalThis;if(globals.document!==undefined){const document=globals.document;const popover=document.querySelector("[data-footnote-popover]");if(popover!==null)activate(Array.from(document.querySelectorAll("[data-footnote-ref]")),popover,document);}